@@ -2012,9 +2012,15 @@ export const combineAxisTicks = (

   let offset = type === 'category' && scale.bandwidth ? scale.bandwidth() / offsetForBand : 0;

+  /*
+   * A categorical angle axis places its band offset in the same direction as the graphical
+   * items that sit on it, whatever direction the axis itself runs in. Deriving the sign from
+   * the range instead flips the offset for an ascending circle, which drifts the axis ticks
+   * away from the points drawn on them and mislabels every category.
+   */
   offset =
     axisType === 'angleAxis' && axisRange != null && axisRange.length >= 2
-      ? mathSign(axisRange[0] - axisRange[1]) * 2 * offset
+      ? (isCategorical && offset !== 0 ? 1 : mathSign(axisRange[0] - axisRange[1])) * 2 * offset
