1	diff --git a/test/chart/polarTooltipAttribution.spec.tsx b/test/chart/polarTooltipAttribution.spec.tsx
2	new file mode 100644
3	index 0000000000..8ed0354cf0
4	--- /dev/null
5	+++ b/test/chart/polarTooltipAttribution.spec.tsx
6	@@ -0,0 +1,427 @@
7	+import React from 'react';
8	+import { act, cleanup, fireEvent, render } from '@testing-library/react';
9	+import { beforeEach, describe, expect, it, vi } from 'vitest';
10	+import { Pie, PieChart, PolarAngleAxis, Radar, RadarChart, Tooltip } from '../../src';
11	+import { mockGetBoundingClientRect } from '../helper/mockGetBoundingClientRect';
12	+import { assertNotNull } from '../helper/assertNotNull';
13	+
14	+/**
15	+ * Behavioural coverage for pointer -> series attribution on a full-circle polar chart.
16	+ *
17	+ * Everything here goes through the public surface only: render a chart, move the pointer over the
18	+ * wrapper, then read what the chart reports (the chart-level mouse handler payload and the rendered
19	+ * tooltip). No module internals are inspected and no expectation is tied to a particular axis
20	+ * orientation, so any fix that makes the chart behave correctly satisfies these tests regardless of
21	+ * where it is implemented.
22	+ */
23	+
24	+const SIZE = 400;
25	+const CX = SIZE / 2;
26	+const CY = SIZE / 2;
27	+const NO_MARGIN = { top: 0, right: 0, bottom: 0, left: 0 };
28	+const PROBE_RADIUS = 110;
29	+
30	+/** Client coordinates of a point at `deg` (0 = 3 o'clock, counter-clockwise) and `radius` from the chart centre. */
31	+function pointAt(deg: number, radius: number): { clientX: number; clientY: number } {
32	+  return {
33	+    clientX: CX + radius * Math.cos((deg * Math.PI) / 180),
34	+    clientY: CY - radius * Math.sin((deg * Math.PI) / 180),
35	+  };
36	+}
37	+
38	+/** Direction of a reported point, measured from the chart centre in the same convention as `pointAt`. */
39	+function directionOf(point: { x: number; y: number }): number {
40	+  return ((((Math.atan2(CY - point.y, point.x - CX) * 180) / Math.PI) % 360) + 360) % 360;
41	+}
42	+
43	+/** Smallest absolute difference between two angles, in degrees. */
44	+function angularGap(a: number, b: number): number {
45	+  const d = (Math.abs((a - b) % 360) + 360) % 360;
46	+  return Math.min(d, 360 - d);
47	+}
48	+
49	+function makeData(count: number): ReadonlyArray<{ name: string; score: number }> {
50	+  return Array.from({ length: count }, (_, i) => ({ name: `series-${i}`, score: 40 + i * 7 }));
51	+}
52	+
53	+type PolarChartOptions = { count: number; startAngle: number; endAngle: number };
54	+
55	+type Reported = {
56	+  label: string;
57	+  coordinate: { x: number; y: number } | undefined;
58	+  direction: number | undefined;
59	+  distance: number;
60	+  active: boolean;
61	+  tooltipText: string;
62	+};
63	+
64	+/**
65	+ * Renders a full-circle RadarChart, moves the pointer to one polar position and returns what the
66	+ * chart reported for it. A fresh render per probe keeps probes independent of each other.
67	+ */
68	+function probe(options: PolarChartOptions, deg: number): Reported {
69	+  cleanup();
70	+  const onMouseMove = vi.fn();
71	+  mockGetBoundingClientRect({ width: SIZE, height: SIZE, left: 0, top: 0 });
72	+  const { container } = render(
73	+    <RadarChart
74	+      width={SIZE}
75	+      height={SIZE}
76	+      data={makeData(options.count)}
77	+      startAngle={options.startAngle}
78	+      endAngle={options.endAngle}
79	+      margin={NO_MARGIN}
80	+      onMouseMove={onMouseMove}
81	+    >
82	+      <PolarAngleAxis dataKey="name" />
83	+      <Radar dataKey="score" isAnimationActive={false} />
84	+      <Tooltip isAnimationActive={false} />
85	+    </RadarChart>,
86	+  );
87	+  act(() => {
88	+    vi.runOnlyPendingTimers();
89	+  });
90	+
91	+  const wrapper = container.querySelector('.recharts-wrapper');
92	+  assertNotNull(wrapper);
93	+  fireEvent.mouseMove(wrapper, pointAt(deg, PROBE_RADIUS));
94	+  act(() => {
95	+    vi.runOnlyPendingTimers();
96	+  });
97	+
98	+  const state: any = onMouseMove.mock.calls[onMouseMove.mock.calls.length - 1]?.[0];
99	+  const coordinate = state?.activeCoordinate;
100	+  return {
101	+    label: String(state?.activeLabel),
102	+    coordinate,
103	+    direction: coordinate ? directionOf(coordinate) : undefined,
104	+    distance: coordinate ? Math.hypot(coordinate.x - CX, coordinate.y - CY) : Infinity,
105	+    active: Boolean(state?.isTooltipActive),
106	+    tooltipText: container.querySelector('.recharts-tooltip-wrapper')?.textContent ?? '',
107	+  };
108	+}
109	+
110	+/**
111	+ * The spokes of a full-circle axis are evenly spaced, so the series a pointer belongs to is the one
112	+ * whose spoke is angularly nearest. Which data index sits on which spoke is the chart's business -
113	+ * these tests only require that the answer is the nearest spoke and that the mapping is one-to-one.
114	+ */
115	+function nearestSpoke(deg: number, count: number, spokeOffset: number): number {
116	+  const step = 360 / count;
117	+  const raw = Math.round((deg - spokeOffset) / step) * step + spokeOffset;
118	+  return ((raw % 360) + 360) % 360;
119	+}
120	+
121	+/** Pointer angles far enough from a spoke boundary that the expected answer is unambiguous. */
122	+function unambiguousAngles(count: number, spokeOffset: number, stepDeg = 5): number[] {
123	+  const half = 180 / count;
124	+  const out: number[] = [];
125	+  for (let deg = 0; deg < 360; deg += stepDeg) {
126	+    if (angularGap(deg, nearestSpoke(deg, count, spokeOffset)) < half - 6) {
127	+      out.push(deg);
128	+    }
129	+  }
130	+  return out;
131	+}
132	+
133	+/**
134	+ * Measures where the chart actually puts its spokes, using a pointer position that resolves
135	+ * correctly on every build, so nothing below hard-codes an axis orientation.
136	+ */
137	+function measureSpokeOffset(options: PolarChartOptions): number {
138	+  const step = 360 / options.count;
139	+  const reference = probe(options, options.startAngle + step / 2 + step);
140	+  expect(reference.direction, 'the reference pointer position must report a point').not.toBeUndefined();
141	+  return (((reference.direction as number) % step) + step) % step;
142	+}
143	+
144	+const CONFIGURATIONS: ReadonlyArray<{ title: string } & PolarChartOptions> = [
145	+  { title: '4 series laid out over 0..360', count: 4, startAngle: 0, endAngle: 360 },
146	+  { title: '5 series laid out over 0..360', count: 5, startAngle: 0, endAngle: 360 },
147	+  { title: '6 series laid out over 45..405', count: 6, startAngle: 45, endAngle: 405 },
148	+  { title: '4 series laid out over 90..450', count: 4, startAngle: 90, endAngle: 450 },
149	+];
150	+
151	+describe('full-circle polar chart pointer attribution', () => {
152	+  beforeEach(() => {
153	+    cleanup();
154	+  });
155	+
156	+  CONFIGURATIONS.forEach(({ title, ...options }) => {
157	+    it(`resolves every pointer angle to the nearest spoke with ${title}`, () => {
158	+      const spokeOffset = measureSpokeOffset(options);
159	+      const angles = unambiguousAngles(options.count, spokeOffset);
160	+      const labelsBySpoke = new Map<number, Set<string>>();
161	+      const problems: string[] = [];
162	+
163	+      angles.forEach(deg => {
164	+        const reported = probe(options, deg);
165	+        const spoke = nearestSpoke(deg, options.count, spokeOffset);
166	+
167	+        if (!reported.active) {
168	+          problems.push(`pointer ${deg}deg: tooltip not active`);
169	+          return;
170	+        }
171	+        if (reported.direction === undefined) {
172	+          problems.push(`pointer ${deg}deg: no highlight position reported`);
173	+          return;
174	+        }
175	+        if (reported.distance > SIZE / 2) {
176	+          problems.push(
177	+            `pointer ${deg}deg: highlight sits ${reported.distance.toFixed(0)}px from the centre, ` +
178	+              `which is off the circle the spokes lie on`,
179	+          );
180	+        }
181	+        if (angularGap(reported.direction, spoke) > 2) {
182	+          problems.push(
183	+            `pointer ${deg}deg: expected the highlight on the spoke at ${spoke.toFixed(0)}deg, ` +
184	+              `got ${reported.direction.toFixed(0)}deg`,
185	+          );
186	+        }
187	+        const seen = labelsBySpoke.get(spoke) ?? new Set<string>();
188	+        seen.add(reported.label);
189	+        labelsBySpoke.set(spoke, seen);
190	+      });
191	+
192	+      expect(problems).toEqual([]);
193	+
194	+      // one series per spoke, and no series shared between two spokes
195	+      labelsBySpoke.forEach((labels, spoke) => {
196	+        expect(Array.from(labels), `spoke at ${spoke}deg must resolve to a single series`).toHaveLength(1);
197	+      });
198	+      const labels = Array.from(labelsBySpoke.values()).map(set => Array.from(set)[0]);
199	+      expect(new Set(labels).size, 'every spoke must own a different series').toBe(labels.length);
200	+    });
201	+  });
202	+
203	+  it('renders the nearest series in the tooltip for a pointer near where the circle wraps', () => {
204	+    const options = { count: 4, startAngle: 0, endAngle: 360 };
205	+    const spokeOffset = measureSpokeOffset(options);
206	+    const deg = 350;
207	+    const reported = probe(options, deg);
208	+
209	+    expect(reported.active).toBe(true);
210	+    expect(reported.direction, 'a highlight position must be reported').not.toBeUndefined();
211	+    expect(angularGap(reported.direction as number, nearestSpoke(deg, options.count, spokeOffset))).toBeLessThanOrEqual(
212	+      2,
213	+    );
214	+    expect(reported.distance).toBeLessThanOrEqual(SIZE / 2);
215	+    expect(reported.tooltipText).toContain(reported.label);
216	+    // and it must not be the series that belongs to the opposite side of the circle
217	+    expect(reported.label).not.toBe(probe(options, (deg + 180) % 360).label);
218	+  });
219	+});
220	+
221	+/**
222	+ * Renders a chart and reads back, for every spoke, which axis label is drawn there and how far from
223	+ * the centre the series point on that spoke is plotted. Purely DOM: no assumption about how the
224	+ * angles are computed, and the radius is only ever compared by rank, so any radial scale is fine.
225	+ */
226	+function readSpokes(
227	+  values: ReadonlyArray<{ name: string; score: number }>,
228	+  options: { startAngle?: number; endAngle?: number } = {},
229	+): Array<{ label: string; radius: number }> {
230	+  cleanup();
231	+  mockGetBoundingClientRect({ width: SIZE, height: SIZE, left: 0, top: 0 });
232	+  const { container } = render(
233	+    <RadarChart width={SIZE} height={SIZE} data={values} margin={NO_MARGIN} {...options}>
234	+      <PolarAngleAxis dataKey="name" />
235	+      <Radar dataKey="score" isAnimationActive={false} dot />
236	+    </RadarChart>,
237	+  );
238	+  act(() => {
239	+    vi.runOnlyPendingTimers();
240	+  });
241	+
242	+  const labels = Array.from(container.querySelectorAll('.recharts-polar-angle-axis-tick-value')).map(el => ({
243	+    text: el.textContent ?? '',
244	+    direction: directionOf({ x: Number(el.getAttribute('x')), y: Number(el.getAttribute('y')) }),
245	+  }));
246	+  const points = Array.from(container.querySelectorAll('.recharts-radar-dot')).map(el => {
247	+    const x = Number(el.getAttribute('cx'));
248	+    const y = Number(el.getAttribute('cy'));
249	+    return { direction: directionOf({ x, y }), radius: Math.hypot(x - CX, y - CY) };
250	+  });
251	+
252	+  expect(labels, 'every series should be labelled').toHaveLength(values.length);
253	+  expect(points, 'every series should be plotted').toHaveLength(values.length);
254	+
255	+  return labels.map(label => {
256	+    const nearest = points
257	+      .slice()
258	+      .sort((a, b) => angularGap(a.direction, label.direction) - angularGap(b.direction, label.direction))[0];
259	+    return { label: label.text, radius: nearest.radius };
260	+  });
